  [407580] = { nil, nil, 0x5c0f8e85, nil, "em" },
  [407627] = { "Aumenta del $N1% la minaccia generata dai tuoi incantesimi sacri e, quando vieni curato dagli incantesimi di altri bersagli alleati, ti conferisce mana pari al $N2% della quantità curata. Inoltre, i danni che portano la tua salute sotto il $N3% sono ridotti del $N4%. Dura $D1.", "Aumenta del $N1% la minaccia generata dai tuoi incantesimi sacri.", 0x5e38b3af, 0x3b84782d, "uu" },
  [407628] = { "Ottieni mana dalle cure ricevute.", nil, 0xd8772002, nil, "um" },
  [407632] = { "Colpisce con il martello il bersaglio attuale e fino a $N1 bersagli aggiuntivi vicini, infliggendo a ciascuno danni da sacro pari a $N2 volte i danni al secondo della tua arma da mano primaria. Condivide il tempo di recupero con ⟦Crusader Strike=Assalto del Crociato⟧.", nil, 0x398ec53c, nil, "um" },
  [407653] = { "Colpisce un nemico con un dardo elettrico che si propaga a un altro nemico vicino. L'incantesimo colpisce fino a $N1 bersagli, infliggendo danni da natura a ciascuno.", "L'aria intorno a te è carica di energia statica.", 0x91b98b1a, 0xe8b6e2de, "uu" },
  [407667] = { "Colpisce un nemico con un dardo elettrico che si ramifica verso tutti i bersagli vicini, infliggendo danni da natura a ciascuno.", nil, 0xc623988a, nil, "um" },
  [407720] = { "Colpisce un nemico con un dardo elettrico che si propaga a un altro nemico vicino. L'incantesimo colpisce fino a $N1 bersagli, infliggendo danni da natura a ciascuno.", nil, 0x91b98b1a, nil, "um" },
  [407736] = { "Colpisce un nemico con un dardo elettrico che si propaga a un altro nemico vicino. L'incantesimo colpisce fino a $N1 bersagli, infliggendo danni da natura a ciascuno.", nil, 0x91b98b1a, nil, "um" },
  [407745] = { "Colpisce un nemico con un dardo elettrico che si ramifica verso tutti i bersagli vicini, infliggendo danni da natura a ciascuno.", nil, 0xc623988a, nil, "um" },
  [407767] = { nil, "L'aria intorno a te è carica di energia statica.", nil, 0xe8b6e2de, "mu" },
  [407778] = { "Un attacco istantaneo con l'arma che infligge il $N1% dei danni dell'arma a un massimo di $N2 nemici entro $N3 m. Tempesta Divina cura fino a $N4 membri del gruppo o dell'incursione per un totale pari al $N5% dei danni inflitti.", nil, 0x2fdbb0b4, nil, "um" },
  [407782] = { "I danni di Tempesta Divina curano i bersagli alleati.", nil, 0x6568a36c, nil, "um" },
  [407784] = { "I danni inflitti da Tempesta Divina curano i bersagli alleati vicini.", nil, 0xd447845f, nil, "um" },
  [407788] = { "Aumenta del $N1% tutti i danni e le cure prodotti per $D1. Provoca Rigorosità e non può essere usato mentre Rigorosità è attiva.", "Tutti i danni e le cure prodotti aumentati del $N1%.", 0x8400caa3, 0x0a348de7, "uu" },
  [407791] = { "Aumenta i danni fisici inflitti dall'incantatore di $N1 e la sua velocità d'attacco del $N2% per $D1.", "Danni fisici inflitti aumentati di $N1.\nVelocità d'attacco aumentata del $N2%.", 0xb2977433, 0xbc6c8e1d, "uu" },
  [407794] = { "Infligge danni fisici a un nemico ogni $D1 per $D2.", "Danni fisici inflitti ogni $D1.", 0x922b6035, 0xc8fd5ef3, "uu" },
  [407798] = { "Ti riempie di spirito sacro per $D1: ognuno dei tuoi attacchi in mischia infligge al bersaglio il $N2% dei danni dell'arma, ma perdi salute pari al $N3% dei danni inflitti. Mentre questo sigillo è attivo, i membri del tuo gruppo e della tua incursione entro $N4 m ottengono ciascuno mana pari al $N5% dei danni che subisci da questo sigillo.\n\nScatenare l'energia di questo sigillo giudica un nemico, infliggendo istantaneamente il $N6% dei danni dell'arma al costo di salute pari al $N7% dei danni inflitti.\n\nIl sigillo e il giudizio di questa abilità beneficiano dei talenti e degli effetti che modificano il sigillo o il giudizio di Sigillo della Rettitudine.", "Gli attacchi in mischia infliggono danni aggiuntivi al bersaglio, ma danneggiano anche te e generano mana per il tuo gruppo e la tua incursione.", 0x78462646, 0xb19ed522, "uu" },
  [407800] = { "I danni di Seal of Martyrdom colpiscono anche il Paladino.", nil, 0x5e5bfe46, nil, "um" },
  [407802] = { "Ottieni mana dai danni subiti dal Paladino.", nil, 0xa57e3739, nil, "um" },
  [407804] = { "Il $N1% di tutti i danni subiti dai membri del gruppo entro $N2 m viene reindirizzato al Paladino per $D1. I danni che portano la salute del Paladino sotto il $N4% interrompono l'effetto e conferiscono al Paladino il $N5% di danni e cure in più per $D2. Divine Sacrifice non può essere usato mentre sei sotto l'effetto di ⟦Blessing of Protection=Benedizione della Protezione⟧, ⟦Divine Shield=Scudo Divino⟧ o ⟦Divine Protection=Protezione Divina⟧, e mentre è attivo impedisce che tu sia bersaglio di quelle abilità.", "Il $N1% di tutti i danni subiti dai membri del gruppo è reindirizzato al Paladino.", 0x9db31be3, 0x9ef73656, "uu" },
  [407805] = { "Danni e cure aumentati dopo il tuo sacrificio.", "Tutti i danni e le cure prodotti aumentati del $N1%.", 0x9fa6d37b, 0x0a348de7, "uu" },
  [407811] = { "Infligge i danni dell'arma e $N1 danni aggiuntivi a un nemico e ai suoi alleati più vicini, colpendo fino a un massimo di $N2 bersagli.", nil, 0xbd91ba0f, nil, "um" },
  [407812] = { nil, "Immune agli effetti di Freccia Congelante.", nil, 0x46871111, "mu" },
