  [407821] = { "Tira contro un bersaglio nemico, infliggendo danni fisici.", nil, 0x75634826, nil, "um" },
  [407880] = { "La tua presenza ispiratrice dissolve periodicamente gli effetti di paura e sonno sui membri del gruppo vicini.", "Dissolve periodicamente gli effetti di paura e sonno sui membri del gruppo vicini.", 0xf32ef617, 0x18985a48, "uu" },
  [407881] = { "La tua presenza ispiratrice dissolve periodicamente gli effetti di paura e sonno sui membri del gruppo vicini.", nil, 0xf32ef617, nil, "um" },
  [407973] = { "Attacco aggiuntivo.", nil, 0xb749f7e9, nil, "um" },
  [407975] = { "I membri del gruppo entro $N1 m ottengono una maggiore ferocia in combattimento. Ogni colpo in mischia ha una probabilità del $N2% di fornire all'attaccante un attacco aggiuntivo con il $N3% di potenza d'attacco in più. Nessun effetto se il membro del gruppo beneficia già del ⟦Windfury Totem=Totem della Furia del Vento⟧.", "Probabilità di ottenere attacchi aggiuntivi.", 0xe5f12b78, 0xa530781b, "uu" },
  [407977] = { "Mentre sei in ⟦Cat Form=Forma Felina⟧, ⟦Bear Form=Forma d'Orso⟧ o Dire Bear Form, i membri del gruppo o dell'incursione entro $N1 m ottengono una maggiore ferocia in combattimento. Ogni colpo in mischia ha una probabilità del $N2% di fornire all'attaccante un attacco aggiuntivo con il $N3% di potenza d'attacco in più. Nessun effetto se il bersaglio beneficia già del ⟦Windfury Totem=Totem della Furia del Vento⟧.", "Probabilità di ottenere attacchi aggiuntivi.", 0xb5f203a6, 0xa530781b, "uu" },
  [407988] = { { "|CFFFFFFFFRichiede ⟦Cat Form=Forma Felina⟧|R\nMossa risolutiva che aumenta del $N1% i danni fisici inflitti in ⟦Cat Form=Forma Felina⟧. La durata aumenta con i punti combo:\n $N2 punto: $N3 s\n $N4 punti: $N5 s\n $N6 punti: $N7 s\n $N8 punti: $N9 s\n $N10 punti: $N11 s", "|CFFFF2020Richiede ⟦Cat Form=Forma Felina⟧|R\nMossa risolutiva che aumenta del $N1% i danni fisici inflitti in ⟦Cat Form=Forma Felina⟧. La durata aumenta con i punti combo:\n $N2 punto: $N3 s\n $N4 punti: $N5 s\n $N6 punti: $N7 s\n $N8 punti: $N9 s\n $N10 punti: $N11 s", shape = { "11/0", "11/0" }, key = { "1e1dd0d422df6e0c", "523eb9e894811201" } }, "Danni fisici inflitti in ⟦Cat Form=Forma Felina⟧ aumentati del $N1%.", 0xac6b876f, 0x4f029a68, "uu" },
  [407989] = { "Mossa risolutiva che aumenta del $N1% i danni fisici inflitti. La durata aumenta con i punti combo:\n $N2 punto: $N3 s\n $N4 punti: $N5 s\n $N6 punti: $N7 s\n $N8 punti: $N9 s\n $N10 punti: $N11 s", "Danni fisici inflitti aumentati del $N1%.", 0x7280611a, 0x07719ea5, "uu" },
